		boolean ownsSession = inherited == null;
		LmdbFusedSipFactorizedRuntime.Session session = ownsSession
				? LmdbFusedSipFactorizedRuntime.create(System.identityHashCode(arg), row.runtimePlan != null)
				: inherited;
